<details>
<summary>interpreter.cpp (killed by 4e7de2ac4cc6c08ff27620de01ccd9d66c568459):  <code>OP_IF</code>/<code>OP_NOTIF</code> tapscript minimal-IF: <code>vch[0] != 1</code> -> <code>vch[0] > 1</code> </summary>

```diff
diff --git a/src/script/interpreter.cpp b/src/script/interpreter.cpp
index 98b16ec..f9b08fe 100644
--- a/src/script/interpreter.cpp
+++ b/src/script/interpreter.cpp
@@ -624,7 +624,7 @@ bool EvalScript(std::vector<std::vector<unsigned char> >& stack, const CScript&
                         if (sigversion == SigVersion::TAPSCRIPT) {
                             // The input argument to the OP_IF and OP_NOTIF opcodes must be either
                             // exactly 0 (the empty vector) or exactly 1 (the one-byte vector with value 1).
-                            if (vch.size() > 1 || (vch.size() == 1 && vch[0] != 1)) {
+                            if (vch.size() > 1 || (vch.size() == 1 && vch[0] > 1)) {
                                 return set_error(serror, SCRIPT_ERR_TAPSCRIPT_MINIMALIF);
                             }
                         }
```

</details>

